describe('Modal Dialog - Escape Key Close Functionality', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should close modal when Escape key is pressed', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Press Escape key
    cy.get('body').type('{esc}');

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify modal content is no longer visible
    cy.get('[data-testid="modal-title"]').should('not.exist');
  });

  it('should not close modal when Escape key is pressed while modal is not open', () => {
    // Verify modal is not visible initially
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Press Escape key
    cy.get('body').type('{esc}');

    // Verify modal is still not visible
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify modal button is still available
    cy.get('[data-testid="open-modal-button"]').should('be.visible');
  });
});
